	/** 
	 * jumpstart the process by instantiating2 ATM
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		aTMId = ATMService.getATMInstance()
		.createATM( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ATMService.getATMInstance()
				.createATM( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.aTMSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for ATM : " + successValue.getATMId());
							  if (successValue.getATMId().equals(aTMId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfATMList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("ATM test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on aTM consumed")
					);
			subscriber.aTMSubscribe( aTMId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for ATM : " + successValue.getATMId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfATMList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on aTM for aTMId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a ATM. 
	 */
	protected ATM read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created ATM" );

		ATM entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read ATM with primary key" );
		msg.append( aTMId );
		
		ATMFetchOneSummary fetchOneSummary = new ATMFetchOneSummary( aTMId );

		try {
			entity = ATMService.getATMInstance().getATM( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found ATM " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a ATM.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a ATM." );

		StringBuilder msg = new StringBuilder( "Failed to update a ATM : " );        
		ATM entity = read();
		UpdateATMCommand command = generateUpdateCommand();
		command.setATMId(entity.getATMId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created ATM." );

			// for use later on...
			aTMId = entity.getATMId();

			ATMService proxy = ATMService.getATMInstance();  

			proxy.updateATM( command ).get();

			LOGGER.info( "-- Successfully saved ATM - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + aTMId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a ATM.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created ATM." );

		ATM entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read ATM with id " + aTMId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read ATM with id " + aTMId );

			throw e;
		}

		try{
			ATMService.getATMInstance().delete( new DeleteATMCommand( entity.getATMId() ) ).get();
			LOGGER.info( "-- Successfully deleted ATM with id " + aTMId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete ATM with id " + aTMId );

			throw e;
		}
	}

	/**
	 * get all ATMs.
	 */
	protected List<ATM> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of ATMs:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all ATM : " );        
		List<ATM> collection  = new ArrayList<>();

		try {
			// call the static get method on the ATMService
			collection = ATMService.getATMInstance().getAllATM();
			assertNotNull( collection, "An Empty collection of ATM was incorrectly returned.");
			
			// Now print out the values
			ATM entity = null;            
			Iterator<ATM> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getATMId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

